DAN_STATIC_STR(dan_lit_1871, "\ntypedef const char *dan_str;\n\n/* At the end of the main program the system frees all memory at once, so the values of the\n   main program are not released one by one. Memory checkers (AddressSanitizer) need every value\n   released: then everything is freed as in any other function. */\n#ifndef DAN_FREE_AT_EXIT\n#if defined(__SANITIZE_ADDRESS__)\n#define DAN_FREE_AT_EXIT 1\n#elif defined(__has_feature)\n#if __has_feature(address_sanitizer)\n#define DAN_FREE_AT_EXIT 1\n#endif\n#endif\n#endif\n#ifndef DAN_FREE_AT_EXIT\n#define DAN_FREE_AT_EXIT 0\n#endif\n\n/* with tasks: the first error stops the program, other tasks wait for the end */\nstatic void (*dan_on_error)(void);\n\n/* A runtime function that returns an error as a value (type \302\253!\302\273) can catch the\n   errors of the parts it is built from: they come back to it here instead of\n   stopping the program. */\n#ifndef __wasi__                   /* WebAssembly has no setjmp: there errors always stop the program */\nstatic DAN_TLS jmp_buf *dan_catch;\nstatic DAN_TLS char dan_caught[512];\nstatic DAN_TLS int dan_caught_line;\n#else\n#define dan_catch NULL\n#endif\n\nstatic void dan_error(const char *text, int line) {\n#ifndef __wasi__\n    if (dan_catch) {\n        snprintf(dan_caught, sizeof dan_caught, \"%s\", text);\n        dan_caught_line = line;\n        longjmp(*dan_catch, 1);\n    }\n#endif\n#ifdef DAN_DEBUG\n    dan_dbg_error(text, line);\n#endif\n    if (dan_on_error) dan_on_error();\n    fflush(stdout);\n    if (line >= DAN_FILE_STEP && line / DAN_FILE_STEP < DAN_FILE_COUNT)\n        fprintf(stderr, DAN_MSG_RUNTIME_FILE, dan_files[line / DAN_FILE_STEP], line % DAN_FILE_STEP, text);\n    else\n        fprintf(stderr, DAN_MSG_RUNTIME, line, text);\n    exit(1);\n}\n\n/* \320\227\320\260\321\211\320\270\321\202\320\260 \320\276\321\202 \320\277\320\265\321\200\320\265\320\277\320\276\320\273\320\275\320\265\320\275\320\270\321\217 \321\201\321\202\320\265\320\272\320\260 \320\277\321\200\320\270 \320\263\320\273\321\203\320\261\320\276\320\272\320\276\320\271 \321\200\320\265\320\272\321\203\321\200\321\201\320\270\320\270. \320\222\320\274\320\265\321\201\321\202\320\276 \320\260\320\262\320\260\321\200\320\270\320\271\320\275\320\276\320\263\320\276\n   \320\267\320\260\320\262\320\265\321\200\321\210\320\265\320\275\320\270\321\217 \320\261\320\265\320\267 \321\201\320\276\320\276\320\261\321\211\320\265\320\275\320\270\321\217 \320\277\321\200\320\276\320\263\321\200\320\260\320\274\320\274\320\260 \320\276\321\201\321\202\320\260\320\275\320\260\320\262\320\273\320\270\320\262\320\260\320\265\321\202\321\201\321\217 \321\201 \320\276\321\210\320\270\320\261\320\272\320\276\320\271 \320\262\321\213\320\277\320\276\320\273\320\275\320\265\320\275\320\270\321\217.\n   \320\241\321\202\320\265\320\272 \321\200\320\260\321\201\321\202\321\221\321\202 \320\262\320\275\320\270\320\267 (x86, ARM); \320\262 \320\275\320\260\321\207\320\260\320\273\320\265 \320\272\320\260\320\266\320\264\320\276\320\271 \321\204\321\203\320\275\320\272\321\206\320\270\320\270 \320\277\321\200\320\276\320\263\321\200\320\260\320\274\320\274\321\213 \321\201\321\200\320\260\320\262\320\275\320\270\320\262\320\260\320\265\321\202\321\201\321\217\n   \320\263\320\273\321\203\320\261\320\270\320\275\320\260 \321\201\321\202\320\265\320\272\320\260 \321\201 \320\277\321\200\320\265\320\264\320\265\320\273\320\276\320\274, \320\262\321\213\321\207\320\270\321\201\320\273\320\265\320\275\320\275\321\213\320\274 \320\262 dan_start \320\277\320\276 \321\200\320\260\320\267\320\274\320\265\321\200\321\203 \321\201\321\202\320\265\320\272\320\260 \320\277\320\276\321\202\320\276\320\272\320\260. */\nstatic DAN_TLS uintptr_t dan_stack_base, dan_stack_limit;\n\nstatic void dan_stack_error(int line) __attribute__((noinline, cold));\nstatic void dan_stack_error(int line) {\n    if (line > 0) dan_error(DAN_MSG_DEEP, line);\n    if (dan_on_error) dan_on_error();\n    fflush(stdout);\n    fprintf(stderr, DAN_MSG_RUNTIME_NOLINE, DAN_MSG_DEEP_DATA);\n    exit(1);\n}\n\n#if defined(__GNUC__) || defined(__clang__)\n#define DAN_FRAME() ((uintptr_t)__builtin_frame_address(0))\n#define DAN_UNLIKELY(x) __builtin_expect(!!(x), 0)\n#else\n#define DAN_FRAME() ((uintptr_t)&dan_probe_)\n#define DAN_UNLIKELY(x) (x)\n#endif\n#ifdef __wasi__\n/* In WebAssembly the call stack of the engine is separate from the memory\n   of the program and cannot be measured, so the depth of calls is counted:\n   10000 calls fit into the stack of every engine, browsers included. */\n#define DAN_WASM_MAX_DEPTH 10000\nstatic int dan_wasm_depth;\nstatic inline void dan_wasm_leave(int *unused) { (void)unused; dan_wasm_depth--; }\n#define DAN_STACK_CHECK(line) __attribute__((cleanup(dan_wasm_leave))) int dan_depth_guard_ = \\\n    (DAN_UNLIKELY(++dan_wasm_depth > DAN_WASM_MAX_DEPTH) \? (dan_stack_error(line), 0) : 0)\n#else\n#define DAN_STACK_CHECK(line) do { char dan_probe_; (void)dan_probe_; \\\n    if (DAN_UNLIKELY(DAN_FRAME() < dan_stack_base - dan_stack_limit)) dan_stack_error(line); } while (0)\n#endif\n\n/* ---- memory: small blocks ----\n   Blocks up to 256 bytes (strings, cells of variants, records, dictionaries, short lists)\n   are the most frequent: they are taken from per-thread lists by size class and returned\n   there, without malloc and free. Blocks of one class are cut from regions of 64 KiB; a\n   two-level table by address tells whether a block belongs to such a region and to which\n   class, so dan_free and dan_realloc accept any pointer (also from malloc). Regions are not\n   returned to the system: their memory is reused. A block freed by another task goes to\n");
DAN_STATIC_STR(dan_lit_1872, "   the list of that task. Under the address sanitizer the lists are off, so that it still\n   finds use after free. */\n#if defined(__SANITIZE_ADDRESS__)\n#define DAN_NO_POOL 1\n#elif defined(__has_feature)\n#if __has_feature(address_sanitizer)\n#define DAN_NO_POOL 1\n#endif\n#endif\n#ifndef DAN_NO_POOL\n#define DAN_SB_SHIFT 16                     /* regions of 64 KiB */\n#define DAN_SB_CLASSES 16                   /* blocks of 16, 32, ..., 256 bytes */\ntypedef struct dan_sblock { struct dan_sblock *next; } dan_sblock;\nstatic DAN_TLS dan_sblock *dan_sb_free[DAN_SB_CLASSES + 1];\nstatic DAN_TLS char *dan_sb_cur[DAN_SB_CLASSES + 1];\nstatic DAN_TLS size_t dan_sb_left[DAN_SB_CLASSES + 1];\nstatic DAN_TLS char *dan_sb_spare;          /* regions not yet given to a class */\nstatic DAN_TLS int dan_sb_spare_n;\nstatic unsigned char *dan_sb_map[1 << 16];  /* region number: high 16 bits -> classes by low 16 bits */\n\nstatic inline int dan_sb_class(const void *p) {\n    uint64_t r = (uint64_t)(uintptr_t)p >> DAN_SB_SHIFT;\n    if (r >> 32) return 0;\n    unsigned char *m = __atomic_load_n(&dan_sb_map[r >> 16], __ATOMIC_ACQUIRE);\n    return m \? m[r & 0xFFFF] : 0;\n}\n\n/* a new region for class c; NULL if the address does not fit the table */\nstatic char *dan_sb_region(int c) {\n    if (!dan_sb_spare_n) {\n        char *slab = malloc((size_t)17 << DAN_SB_SHIFT);\n        if (!slab) return NULL;\n        dan_sb_spare = (char *)(((uintptr_t)slab + ((uintptr_t)1 << DAN_SB_SHIFT) - 1) & ~(((uintptr_t)1 << DAN_SB_SHIFT) - 1));\n        dan_sb_spare_n = 16;\n    }\n    char *g = dan_sb_spare;\n    uint64_t r = (uint64_t)(uintptr_t)g >> DAN_SB_SHIFT;\n    if (r >> 32) return NULL;\n    unsigned char *m = __atomic_load_n(&dan_sb_map[r >> 16], __ATOMIC_ACQUIRE);\n    if (!m) {\n        unsigned char *n = calloc((size_t)1 << 16, 1), *expected = NULL;\n        if (!n) return NULL;\n        if (__atomic_compare_exchange_n(&dan_sb_map[r >> 16], &expected, n, 0, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) m = n;\n        else { free(n); m = expected; }\n    }\n    __atomic_store_n(&m[r & 0xFFFF], (unsigned char)c, __ATOMIC_RELEASE);\n    dan_sb_spare += (size_t)1 << DAN_SB_SHIFT;\n    dan_sb_spare_n--;\n    return g;\n}\n\nstatic inline void *dan_sb_alloc(size_t n) {\n    int c = n \? (int)((n + 15) >> 4) : 1;\n    dan_sblock *b = dan_sb_free[c];\n    if (b) { dan_sb_free[c] = b->next; return b; }\n    size_t size = (size_t)c * 16;\n    if (dan_sb_left[c] < size) {\n        char *g = dan_sb_region(c);\n        if (!g) return NULL;\n        dan_sb_cur[c] = g;\n        dan_sb_left[c] = (size_t)1 << DAN_SB_SHIFT;\n    }\n    void *p = dan_sb_cur[c];\n    dan_sb_cur[c] += size;\n    dan_sb_left[c] -= size;\n    return p;\n}\n#endif\n\nstatic void *dan_alloc(size_t n) {\n#ifndef DAN_NO_POOL\n    if (n <= DAN_SB_CLASSES * 16) {\n        void *b = dan_sb_alloc(n);\n        if (b) return b;\n    }\n#endif\n    void *p = malloc(n \? n : 1);\n    if (!p) dan_error(DAN_MSG_NO_MEMORY, 0);\n    return p;\n}\n\nstatic void dan_free(void *p) {\n#ifndef DAN_NO_POOL\n    int c = dan_sb_class(p);\n    if (c) {\n        dan_sblock *b = p;\n        b->next = dan_sb_free[c];\n        dan_sb_free[c] = b;\n        return;\n    }\n#endif\n    free(p);\n}\n\nstatic void *dan_realloc(void *p, size_t n) {\n#ifndef DAN_NO_POOL\n    int c = dan_sb_class(p);\n    if (c) {\n        size_t size = (size_t)c * 16;\n        if (n <= size) return p;\n        void *r = dan_alloc(n);\n        memcpy(r, p, size);\n        dan_free(p);\n        return r;\n    }\n    if (!p) return dan_alloc(n);\n#endif\n    p = realloc(p, n \? n : 1);\n    if (!p) dan_error(DAN_MSG_NO_MEMORY, 0);\n    return p;\n}\n\n/* ---- memory: reference counting ----\n   Every value kept in memory (string, list, dictionary, bytes, variant cell,\n   environment of a closure) starts with a header. rc is the number of places\n   (variables, fields, elements) that hold the value; a value that is only in\n   use as a temporary has rc == 0. A new value is put into the table of\n");
DAN_STATIC_STR(dan_lit_1873, "   temporaries (ZCT); at the end of each statement the table is swept, and\n   values that no place holds are freed. A value whose last place lets it go\n   is freed at once. Freeing is iterative, so long chains do not overflow\n   the stack. Values never form cycles (they are values, not shared objects),\n   so no garbage collector is needed. */\ntypedef struct { int32_t rc; uint16_t flags; uint16_t magic; } dan_hdr;\n#define DAN_MAGIC 0xDA4E\n#define DAN_IN_ZCT 1u\n#define DAN_IMMORTAL 2u\n#define DAN_HDR_INIT { 0, DAN_IMMORTAL, DAN_MAGIC }\ntypedef void (*dan_destroy_fn)(dan_hdr *);\ntypedef struct { dan_hdr *h; dan_destroy_fn d; } dan_zent;\nstatic DAN_TLS dan_zent *dan_zct, *dan_dead;\nstatic DAN_TLS size_t dan_zct_n, dan_zct_cap, dan_dead_n, dan_dead_cap;\nstatic DAN_TLS int dan_draining;\n\nstatic void dan_zct_push(dan_hdr *h, dan_destroy_fn d) {\n    if (h->flags & (DAN_IN_ZCT | DAN_IMMORTAL)) return;\n    h->flags |= DAN_IN_ZCT;\n    if (dan_zct_n == dan_zct_cap) {\n        dan_zct_cap = dan_zct_cap \? dan_zct_cap * 2 : 256;\n        dan_zct = dan_realloc(dan_zct, dan_zct_cap * sizeof *dan_zct);\n    }\n    dan_zct[dan_zct_n].h = h;\n    dan_zct[dan_zct_n].d = d;\n    dan_zct_n++;\n}\n\nstatic void dan_kill(dan_hdr *h, dan_destroy_fn d) {\n    if (dan_dead_n == dan_dead_cap) {\n        dan_dead_cap = dan_dead_cap \? dan_dead_cap * 2 : 256;\n        dan_dead = dan_realloc(dan_dead, dan_dead_cap * sizeof *dan_dead);\n    }\n    dan_dead[dan_dead_n].h = h;\n    dan_dead[dan_dead_n].d = d;\n    dan_dead_n++;\n    if (dan_draining) return;\n    dan_draining = 1;\n    while (dan_dead_n) {\n        dan_zent e = dan_dead[--dan_dead_n];\n        e.d(e.h);\n    }\n    dan_draining = 0;\n}\n\nstatic inline size_t dan_mark(void) { return dan_zct_n; }\n\n#define DAN_MAGIC_SHARED 0xDA4F   /* value shared between tasks (channel): counted under a lock */\nstatic void dan_sweep_slow(size_t m) {\n    while (dan_zct_n > m) {\n        dan_zent e = dan_zct[--dan_zct_n];\n        if (e.h->magic == DAN_MAGIC_SHARED) { e.d(e.h); continue; }\n        e.h->flags &= (uint16_t)~DAN_IN_ZCT;\n        if (e.h->rc == 0) dan_kill(e.h, e.d);\n    }\n}\nstatic inline void dan_sweep(size_t m) { if (dan_zct_n > m) dan_sweep_slow(m); }\n\n/* a value made for another task: one place (the message) holds it, no table */\nstatic inline void dan_hdr_detached(dan_hdr *h) { h->rc = 1; h->flags = 0; h->magic = DAN_MAGIC; }\n\nstatic inline void dan_hdr_new(dan_hdr *h, dan_destroy_fn d) {\n    h->rc = 0; h->flags = 0; h->magic = DAN_MAGIC;\n    dan_zct_push(h, d);\n}\nstatic inline void dan_hdr_share(dan_hdr *h) { if (!(h->flags & DAN_IMMORTAL)) h->rc++; }\nstatic inline void dan_hdr_release(dan_hdr *h, dan_destroy_fn d) {\n    if (h->flags & DAN_IMMORTAL) return;\n    if (--h->rc <= 0) { h->rc = 0; if (!(h->flags & DAN_IN_ZCT)) dan_kill(h, d); }\n}\n/* the place passes the value on (to the caller): it becomes a temporary */\nstatic inline void dan_hdr_give(dan_hdr *h, dan_destroy_fn d) {\n    if (h->flags & DAN_IMMORTAL) return;\n    if (--h->rc <= 0) { h->rc = 0; dan_zct_push(h, d); }\n}\n\n#define DAN_XSTR_(x) #x\n#define DAN_XSTR(x) DAN_XSTR_(x)\n#define DAN_SYM(n) DAN_XSTR(__USER_LABEL_PREFIX__) n\n#define DAN_ID(x) (x)\n#define DAN_NOREL(x) ((void)0)\n\n/* environment of a closure: header, its own way to free the captured values */\ntypedef struct { dan_hdr h; dan_destroy_fn d; void *(*c)(const void *); } dan_envb;\nstatic inline void dan_env_share(void *e) { if (e) dan_hdr_share(&((dan_envb *)e)->h); }\nstatic inline void dan_env_release(void *e) { if (e) dan_hdr_release(&((dan_envb *)e)->h, ((dan_envb *)e)->d); }\nstatic inline void dan_env_give(void *e) { if (e) dan_hdr_give(&((dan_envb *)e)->h, ((dan_envb *)e)->d); }\nstatic inline void *dan_env_clone(void *e) { return e \? ((dan_envb *)e)->c(e) : NULL; }\n\n/* Strings: the header is right before the characters. Text that did not\n   come from dan_str_new (a C literal) has no header and is never freed. */\n/* Short strings are the most frequent values: their blocks come from the lists of small\n");
DAN_STATIC_STR(dan_lit_1874, "   blocks (dan_alloc), without malloc and free. */\nstatic void dan_str_destroy(dan_hdr *h) { dan_free(h); }\nstatic char *dan_str_new(size_t n) {\n    dan_hdr *h = dan_alloc(sizeof *h + n + 1);\n    dan_hdr_new(h, dan_str_destroy);\n    char *s = (char *)(h + 1);\n    s[n] = 0;\n    return s;\n}\nstatic inline dan_hdr *dan_str_hdr(dan_str s) {\n    uint16_t m;\n    if (!s) return NULL;\n    memcpy(&m, s - 2, 2);\n    return m == DAN_MAGIC \? (dan_hdr *)(void *)(s - sizeof(dan_hdr)) : NULL;\n}\nstatic inline dan_str dan_str_share(dan_str s) { dan_hdr *h = dan_str_hdr(s); if (h) dan_hdr_share(h); return s; }\nstatic inline void dan_str_release(dan_str s) { dan_hdr *h = dan_str_hdr(s); if (h) dan_hdr_release(h, dan_str_destroy); }\nstatic inline void dan_str_give(dan_str s) { dan_hdr *h = dan_str_hdr(s); if (h) dan_hdr_give(h, dan_str_destroy); }\n/* copy for another task (strings that are never freed are shared as they are) */\nstatic dan_str dan_str_clone(dan_str s) {\n    dan_hdr *h = dan_str_hdr(s);\n    if (!h || (h->flags & DAN_IMMORTAL)) return s;\n    size_t n = strlen(s);\n    dan_hdr *r = dan_alloc(sizeof *r + n + 1);\n    dan_hdr_detached(r);\n    memcpy(r + 1, s, n + 1);\n    return (char *)(r + 1);\n}\n#define DAN_STATIC_STR(name, text) \\\n    static const struct { dan_hdr h; char s[sizeof(text)]; } name = { DAN_HDR_INIT, text }\nDAN_STATIC_STR(dan_true_s, DAN_TRUE);\nDAN_STATIC_STR(dan_false_s, DAN_FALSE);\nDAN_STATIC_STR(dan_empty_s, \"\");\n\nstatic void dan_index_error(int64_t i, int64_t len, int line) {\n    char buf[200];\n    snprintf(buf, sizeof buf, DAN_MSG_INDEX, (long long)i, (long long)len);\n    dan_error(buf, line);\n}\n\nstatic void dan_conv_error(const char *fmt, dan_str s, int line) {\n    char buf[300];\n    snprintf(buf, sizeof buf, fmt, s);\n    dan_error(buf, line);\n}\n\n/* ---- arithmetic ---- */\n\n/* Integer overflow is never silent: the result is either exact or the\n   program stops with a message (no undefined behaviour, no wraparound). */\nstatic inline int64_t dan_add(int64_t a, int64_t b, int line) {\n    int64_t r;\n    if (__builtin_add_overflow(a, b, &r)) dan_error(DAN_MSG_TOO_BIG, line);\n    return r;\n}\n\nstatic inline int64_t dan_sub(int64_t a, int64_t b, int line) {\n    int64_t r;\n    if (__builtin_sub_overflow(a, b, &r)) dan_error(DAN_MSG_TOO_BIG, line);\n    return r;\n}\n\nstatic inline int64_t dan_mul(int64_t a, int64_t b, int line) {\n    int64_t r;\n    if (__builtin_mul_overflow(a, b, &r)) dan_error(DAN_MSG_TOO_BIG, line);\n    return r;\n}\n\nstatic inline int64_t dan_neg(int64_t a, int line) {\n    if (a == INT64_MIN) dan_error(DAN_MSG_TOO_BIG, line);\n    return -a;\n}\n\n/* Division with remainder as defined in school mathematics:\n   a = b * q + r, where 0 <= r < |b|. The remainder is never negative,\n   so -7 : 2 = -4 (remainder 1), and -7 % 3 == 2. */\nstatic int64_t dan_div(int64_t a, int64_t b, int line) {\n    if (b == 0) dan_error(DAN_MSG_DIV_ZERO, line);\n    if (a == INT64_MIN && b == -1) dan_error(DAN_MSG_TOO_BIG, line);\n    int64_t q = a / b, r = a % b;\n    if (r < 0) q += b > 0 \? -1 : 1;\n    return q;\n}\n\n/* \320\242\320\276\321\207\320\275\320\276\320\265 \320\264\320\265\320\273\320\265\320\275\320\270\320\265 \321\206\320\265\320\273\321\213\321\205 \321\202\320\260\320\274, \320\263\320\264\320\265 \321\207\320\260\321\201\321\202\320\275\320\276\320\265 \320\276\320\261\321\217\320\267\320\260\320\275\320\276 \320\261\321\213\321\202\321\214 \321\206\320\265\320\273\321\213\320\274 (\320\277\320\260\321\200\320\260\320\274\320\265\321\202\321\200 \321\202\320\270\320\277\320\260\n   \320\247\320\270\321\201\320\273\320\276\320\262\320\276\320\265 \321\201\320\276 \320\267\320\275\320\260\321\207\320\265\320\275\320\270\320\265\320\274 \321\206\320\265\320\273): \320\265\321\201\320\273\320\270 \320\276\321\201\321\202\320\260\321\202\320\276\320\272 \320\275\320\265 \320\275\320\276\320\273\321\214, \321\215\321\202\320\276 \320\276\321\210\320\270\320\261\320\272\320\260, \320\260 \320\275\320\265 \320\276\320\272\321\200\321\203\320\263\320\273\320\265\320\275\320\270\320\265. */\nstatic void dan_not_exact(const char *a, const char *b, int line) {\n    char buf[300];\n    snprintf(buf, sizeof buf, DAN_MSG_NOT_EXACT, a, b);\n    dan_error(buf, line);\n}\nstatic int64_t dan_div_exact(int64_t a, int64_t b, int line) {\n    int64_t q = dan_div(a, b, line);\n    if (q * b != a) {\n        char x[32], y[32];\n        snprintf(x, sizeof x, \"%lld\", (long long)a);\n        snprintf(y, sizeof y, \"%lld\", (long long)b);\n        dan_not_exact(x, y, line);\n    }\n    return q;\n}\n\nstatic int64_t dan_mod(int64_t a, int64_t b, int line) {\n    if (b == 0) dan_error(DAN_MSG_MOD_ZERO, line);\n    if (b == -1 || b == 1) return 0;\n    int64_t r = a % b;\n    if (r < 0) r += b > 0 \? b : -b;\n    return r;\n}\n\n/* ---- strings ---- */\n\nstatic dan_str dan_strdup(const char *s) {\n");
