static bool dm_Dib_eq(const dm_Dib *x, const dm_Dib *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_Dib_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        bool a = x->vals[e]; bool b = y->vals[f];
        if (!((a == b))) return false;
    }
    return true;
}


